mapper.select:
SELECT *, '' AS DomainName FROM tCodModel

    AND SystemCode = #{pSystemCode}
    AND DomainCode = #{pDomainCode}

        AND (CONCAT(IFNULL(KorWord1,''),IFNULL(KorWord2,''),IFNULL(KorWord3,''),IFNULL(KorWord4,''),IFNULL(KorWord5,'')) LIKE CONCAT('%',#{pModelName},'%')
        OR CONCAT(IFNULL(EngAbbr1,''),IFNULL(EngAbbr2,''),IFNULL(EngAbbr3,''),IFNULL(EngAbbr4,''),IFNULL(EngAbbr5,'')) LIKE CONCAT('%',#{pModelName},'%'))



    ORDER BY ${sidx} ${sord}

mapper.update:
UPDATE tCodModel SET
DomainCode = #{domainCode}, KorWord1 = #{korWord1}, KorWord2 = #{korWord2}, KorWord3 = #{korWord3}, KorWord4 = #{korWord4},
KorWord5 = #{korWord5}, EngAbbr1 = #{engAbbr1}, EngAbbr2 = #{engAbbr2}, EngAbbr3 = #{engAbbr3}, EngAbbr4 = #{engAbbr4},
EngAbbr5 = #{engAbbr5}, AlterName = #{alterName}, State = #{state}, Remark = #{remark},
ChangeDate = NOW(), ChangeId = #{changeId}, ChangeName = #{changeName}
WHERE ModelId = #{modelId}
